def f(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    rows=[r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=bg]
    cols=[c for c in range(W) if len({g[r][c] for r in range(H)})==1 and g[0][c]!=bg]
    out=[r[:] for r in g]
    cells=[(r,c,g[r][c]) for r in range(H) for c in range(W)
           if g[r][c]!=bg and not (r in rows) and not (c in cols)]
    rs=[r for r,c,v in cells]; cs=[c for r,c,v in cells]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    rb=sorted(rows); cb=sorted(cols)
    def intervals(boundaries):
        res=[];prev=-1
        for b in boundaries:
            if prev+1<=b-1: res.append((prev+1,b))
            prev=b
        if prev+1<W or True: 
            pass
        return res+[ (prev+1, bound-1 if bound<H else W-1) ] if False else None
    # simpler: intervals of non-bar rows
    rr=[];prev=-1
    for r in range(H):
        if r in rows:
            if prev+1<=r-1: rr.append((prev+1,r-1))
            prev=r
    if prev+1<H: rr.append((prev+1,H-1))
    cc=[];prev=-1
    for c in range(W):
        if c in cols:
            if prev+1<=c-1: cc.append((prev+1,c-1))
            prev=c
    if prev+1<W: cc.append((prev+1,W-1))
    mr=[i for i,(a,b) in enumerate(rr) if a<=r0<=b][0]
    mc=[j for j,(a,b) in enumerate(cc) if a<=c0<=b][0]
    origins_r={k:v[0] for k,v in zip(range(len(rr)),rr)}
    origins_c={k:v[0] for k,v in zip(range(len(cc)),cc)}
    rel=[(r-origins_r[mr],c-origins_c[mc],v) for r,c,v in cells]
    for ri in range(len(rr)):
        for cj in range(len(cc)):
            for dr,dc,v in rel:
                r=origins_r[ri]+dr; cc2=origins_c[cj]+dc
                if 0<=r<H and 0<=cc2<W: out[r][cc2]=v
    return out
